bool lighting=true,mapping=true,normalMaps=true,environment=true,wire=false,loading=true;int width=1440,height=900,lastX=0,lastY=0,selected=0;GLuint fontBase=0,skyTexture=0;double clockTime=0,simulation=0,fps=0;size_t triangles=0;std::string action="READY | 1: town  2: boats  3: drone  Space: start 26-second race";WideLog logFile;
void aim(Vec3 eye,Vec3 target){camera.eye=eye;Vec3 d=unit(target-eye);camera.yaw=atan2(d.z,d.x)*180/3.141592653589793;camera.pitch=asin(d.y)*180/3.141592653589793;}
double raceScale(){return boat.distances.back()*.985/std::max(race.at(0,26).distance,race.at(1,26).distance);}
double progress(int team,double t){return race.at(team,t).distance*raceScale()/boat.distances.back();}
Vec3 boatDirection(int team,double t){return fromZup(boat.direction(progress(team,t)));}
Vec3 boatPosition(int team,double t){Vec3 dir=boat.direction(progress(team,t));double lane=team==0?-2.05:2.05;return fromZup(boat.at(progress(team,t))+Vec3{-dir.y*lane,dir.x*lane,0});}
double crewPhase(int team){return trajectory?race.at(team,simulation).cycles:0;}
Vec3 raceTarget(){return (boatPosition(0,simulation)+models[0].translation+boatPosition(1,simulation)+models[1].translation)*.5+boatDirection(0,simulation)*1.2+Vec3{0,1.15,0};}
void preset(int n){
 follow=false;cameraFov=48;
 if(n==1)aim({75,70,90},{0,3,0});
 else if(n==2){if(selected==2)aim({7,8,16},{0,2,0});else {Vec3 p=boatPosition(selected,trajectory?simulation:0)+models[selected].translation;cameraFov=56;aim(p+Vec3{8.5,6.5,3},p+Vec3{0,1,0});}}
 else if(n==3){
  follow=true;Vec3 target=raceTarget();
  aim(fromZup(flight.at(simulation)),target);
  // Smoothly retreat along the viewing ray when a close shot would require
  // an excessively wide lens. A smooth positive part + L8 norm avoids snaps.
  double pullPower=0,limit=tan(64*3.141592653589793/360);
  for(int team=0;team<2;++team)for(double x:{-6.1,6.1})for(double y:{-.35,3.25})for(double z:{-2.0,2.0}){
   Vec3 dir=boatDirection(team,simulation),p=boatPosition(team,simulation)+models[team].translation+Vec3{dir.x*x-dir.z*z,y,dir.z*x+dir.x*z}-camera.eye;double depth=dot(p,camera.front());
   double deficits[]={std::abs(dot(p,camera.right()))/(limit*(double(width)/height)*.90)-depth,dot(p,camera.up())/(limit*.68)-depth,-dot(p,camera.up())/(limit*.90)-depth,.3-depth};
   for(double d:deficits){double positive=.5*(d+sqrt(d*d+.09));pullPower+=pow(positive,8);}
  }
  camera.eye=camera.eye-camera.front()*pow(pullPower,.125);double needed=tan(flight.fov(simulation)*3.141592653589793/360);
  for(int team=0;team<2;++team)for(double x:{-6.1,6.1})for(double y:{-.35,3.25})for(double z:{-2.0,2.0}){
   Vec3 dir=boatDirection(team,simulation),p=boatPosition(team,simulation)+models[team].translation+Vec3{dir.x*x-dir.z*z,y,dir.z*x+dir.x*z};Vec3 d=p-camera.eye;double depth=dot(d,camera.front());
   if(depth>.2){needed=std::max(needed,std::abs(dot(d,camera.right()))/(depth*(double(width)/height)*.90));needed=std::max(needed,dot(d,camera.up())/(depth*.68));needed=std::max(needed,-dot(d,camera.up())/(depth*.90));}
  }
  cameraFov=std::min(78.0,atan(needed)*360/3.141592653589793);
 }else aim({58,26,-61},{20,7,-35});
}
