void checkCinematicFrame(){double tangent=tan(cameraFov*3.141592653589793/360);for(int team=0;team<2;++team)for(double x:{-6.1,6.1})for(double y:{-.35,3.25})for(double z:{-2.,2.}){Vec3 d=boatDirection(team,simulation),p=boatPosition(team,simulation)+Vec3{d.x*x-d.z*z,y,d.z*x+d.x*z}-camera.eye;double depth=dot(p,camera.front()),sx=dot(p,camera.right())/(depth*tangent*width/height),sy=dot(p,camera.up())/(depth*tangent);if(depth<.2||std::abs(sx)>.96||sy>.74||sy<-.96)throw std::runtime_error("Cinematic boat framing exceeded the safe viewport");}}
void bindTexture(int unit,GLuint id){gpu.active(0x84C0+unit);glBindTexture(GL_TEXTURE_2D,id);gpu.active(0x84C0);}
void drawMaterial(const Material& m,int mode){int surface=0;const auto& name=m.name;if(name=="panorama_ground"||name=="huizhou_earth"||name=="hill_far"||name=="river_silt"||name=="river_gravel")surface=1;else if(name=="huizhou_white"||name=="plaster")surface=2;else if(name=="roof")surface=3;else if(name=="huizhou_path"||name=="huizhou_masonry"||name=="cut_limestone"||name=="paving"||name=="stone")surface=4;else if(name=="rural_tree_atlas")surface=7;else if(name.rfind("lod_tree_1",0)==0)surface=8;else if(name.find("male_casualsuit")!=name.npos)surface=5;if(m.colorFile.filename().wstring().find(L"middleage")!=std::wstring::npos)surface=6;shader.integer("isPerson",0);shader.vector("characterTint",{1,1,1});shader.integer("surfaceType",surface);shader.vector("fabricColor",{.23,.28,.25});shader.vector("baseColor",m.color);shader.scalar("shininess",m.shine);shader.scalar("specularStrength",m.specular);shader.integer("mode",mode);shader.integer("useTexture",mapping&&m.colorMap!=0);shader.integer("useNormals",normalMaps&&m.normalMap!=0&&mode==0);bindTexture(0,m.colorMap);bindTexture(1,m.normalMap);}
void applyBoat(int team){
    auto& m=models[team];Vec3 p=boatPosition(team,0);double angle=0;
    if(trajectory){p=boatPosition(team,simulation);Vec3 dir=boatDirection(team,simulation);angle=atan2(-dir.z,dir.x)*180/3.141592653589793;}
    p=p+m.translation;glTranslated(p.x,p.y,p.z);glRotated(angle+m.rotation.y,0,1,0);glRotated(m.rotation.x,1,0,0);glRotated(m.rotation.z,0,0,1);glScaled(m.scale,m.scale,m.scale);
}
void applyPaddle(const Batch& b){if(b.motion==30){auto orientation=flagOrientation();glMultMatrixd(orientation.data());return;}if(b.motion>=20){int side=b.motion==20?-1:1;auto p=drumPose(crewPhase(b.entity-1),side);Vec3 grip{3.89,1.77,-side*.22};glTranslated(grip.x+p.lift,grip.y+p.lift,grip.z);glRotated(-p.angle,0,0,1);glTranslated(-grip.x,-grip.y,-grip.z);return;}if(b.motion<=0)return;int row=(b.motion-1)/2,side=(b.motion-1)%2?1:-1;auto p=paddlePose(crewPhase(b.entity-1));Vec3 pivot{-3+1.1*row+.42,1.51,-side*.66};glTranslated(pivot.x+p.reach,pivot.y+p.lift,pivot.z);glRotated(p.angle,0,0,1);glRotated(side*p.feather,1,0,0);glTranslated(-pivot.x,-pivot.y,-pivot.z);}
Vec3 localToWorld(int team,double t,Vec3 p){Vec3 d=boatDirection(team,t);return boatPosition(team,t)+Vec3{d.x*p.x-d.z*p.z,p.y,d.z*p.x+d.x*p.z};}
void waterUniforms(){
    shader.integer("raceActive",trajectory);shader.scalar("raceTime",simulation);
    for(int team=0;team<2;++team){
        for(int j=0;j<12;++j){double age=j*.20,t=std::max(0.0,simulation-age);Vec3 p=localToWorld(team,t,{-4.65,0,0});std::string index="wake["+std::to_string(team*12+j)+"]";shader.vector(index.c_str(),{p.x,p.z,simulation>=age?age:-1});}
        auto sample=race.at(team,simulation);double catchCycle=floor(sample.cycles-.10)+.10,lo=0,hi=simulation;
        for(int i=0;i<20;++i){double mid=(lo+hi)*.5;if(race.at(team,mid).cycles<catchCycle)lo=mid;else hi=mid;}
        double t=(lo+hi)*.5,age=simulation-t;
        for(int row=0;row<6;++row)for(int side:{-1,1}){Vec3 p=localToWorld(team,t,paddlePoint(row,side,-1.53,.10));std::string index="ripples["+std::to_string(team*12+row*2+(side>0?1:0))+"]";shader.vector(index.c_str(),{p.x,p.z,catchCycle>=.1?age:-1});}
        auto name="boatSpeed["+std::to_string(team)+"]";shader.vector(name.c_str(),{sample.speed*raceScale(),0,0});
        name="boatPosition["+std::to_string(team)+"]";shader.vector(name.c_str(),boatPosition(team,simulation));
        name="boatDirection["+std::to_string(team)+"]";shader.vector(name.c_str(),boatDirection(team,simulation));
    }
}
void drawCrew(){for(int team=0;team<2;++team){crew.update(crewPhase(team),team);GPU& crewMesh=crew.meshFor(team);crewMesh.begin();glPushMatrix();applyBoat(team);
    for(auto& b:crewMesh.batches){drawMaterial(materials[b.material],0);shader.integer("isPerson",1);shader.vector("personHead",crew.headCenters[team]);for(int row=0;row<6;++row)for(int side:{-1,1}){glPushMatrix();glTranslated(-3+1.1*row,.82,-side*.40);glScaled(1,1,side);glFrontFace(side<0?GL_CW:GL_CCW);double variation=.88+.18*sin(row*3.7+side*1.8+team);shader.vector("fabricColor",(team==0?Vec3{.45,.10,.08}:Vec3{.16,.28,.31})*variation);shader.vector("characterTint",{.96+.08*sin(row*3.1+side),.94+.07*cos(row*2.7+team),.91+.08*sin(row*2.1+team)});shader.vector("personStyle",{.055*sin(row*2.3+side),.012*cos(row*3.1+team),.055*sin(row*1.7+team+side)});crewMesh.draw(b);glPopMatrix();}}glFrontFace(GL_CCW);glPopMatrix();crewMesh.end();}}
