void tick(double dt){clockTime+=dt;if(playing&&!leftDown&&!rightDown){simulation=std::min(26.0,simulation+dt);if(simulation>=26)playing=false;}
    auto& m=models[selected];double d=dt*4,a=dt*40;if(keys[VK_LEFT])m.translation.x-=d;if(keys[VK_RIGHT])m.translation.x+=d;if(keys[VK_UP])m.translation.z-=d;if(keys[VK_DOWN])m.translation.z+=d;if(keys[VK_PRIOR])m.translation.y+=d;if(keys[VK_NEXT])m.translation.y-=d;
    if(keys['Q'])m.rotation.y-=a;if(keys['E'])m.rotation.y+=a;if(keys['I'])m.rotation.x+=a;if(keys['K'])m.rotation.x-=a;if(keys['J'])m.rotation.z+=a;if(keys['L'])m.rotation.z-=a;
    if(keys[VK_OEM_PLUS]||keys[VK_ADD])m.scale*=exp(dt*.6);if(keys[VK_OEM_MINUS]||keys[VK_SUBTRACT])m.scale*=exp(-dt*.6);m.scale=std::clamp(m.scale,.2,3.0);
    if(!follow){double speed=dt*(keys[VK_SHIFT]?45:12);if(keys['W'])camera.eye=camera.eye+camera.front()*speed;if(keys['S'])camera.eye=camera.eye-camera.front()*speed;if(keys['A'])camera.eye=camera.eye-camera.right()*speed;if(keys['D'])camera.eye=camera.eye+camera.right()*speed;}
    else {preset(3);if(trajectory&&playing)action=flight.stage(simulation);}
}
