 if(landscapeDetails.vertices){landscapeDetails.begin();for(const auto& tree:treeInstances){Batch bound;double r=4*tree.scale;Vec3 c=tree.position+Vec3{0,2.1*tree.scale,0};bound.boundsMin=c-Vec3{r,r,r};bound.boundsMax=c+Vec3{r,r,r};if(!depthPass&&!visibleStaticBatch(bound))continue;glPushMatrix();glTranslated(tree.position.x,tree.position.y,tree.position.z);glRotated(tree.angle,0,1,0);glScaled(tree.scale,tree.scale,tree.scale);for(auto& b:landscapeDetails.batches){drawMaterial(materials[b.material],0);landscapeDetails.draw(b);if(!depthPass)drawnStaticTriangles+=b.count/3;}glPopMatrix();}landscapeDetails.end();}
 if(villageDetails.vertices){villageDetails.begin();for(auto& b:villageDetails.batches){if(!depthPass&&!visibleStaticBatch(b))continue;drawMaterial(materials[b.material],0);villageDetails.draw(b);if(!depthPass)drawnStaticTriangles+=b.count/3;}villageDetails.end();}
 if(understory.vertices){understory.begin();for(auto& b:understory.batches){if(!depthPass&&!visibleStaticBatch(b))continue;drawMaterial(materials[b.material],0);understory.draw(b);if(!depthPass)drawnStaticTriangles+=b.count/3;}understory.end();}
