 if(frame==9){key('H');preset(2);}if(frame==10){key('H');double scale=models[0].scale;keys[VK_ADD]=true;keys['E']=true;tick(.4);keys[VK_ADD]=false;keys['E']=false;if(models[0].scale<=scale||models[0].rotation.y<15)throw std::runtime_error("Model scale/rotation verification failed");}
 if(frame==11){auto p=root/L"results/import_test.obj";FILE* f=_wfopen(p.c_str(),L"wb");if(!f)throw std::runtime_error("Import fixture failed");const char* data="v 0 0 0\nv 2 0 0\nv 0 2 0\nf 1 2 3\n";fwrite(data,1,strlen(data),f);fclose(f);loadExtra(p);if(selected!=2||!extra.vertices)throw std::runtime_error("OBJ import verification failed");}
 if(frame==12){reset();key(VK_SPACE);for(int i=0;i<1561;++i)tick(1.0/60);if(std::abs(simulation-26)>.00001||playing||!follow||length(camera.eye-fromZup(flight.at(26)))>.1)throw std::runtime_error("Full 26-second timeline / drone integration failed");}
 if(frame>=13&&frame<=15){reset();selected=0;models[2].translation.y=-100;trajectory=true;double target=1+(frame==13?.10:frame==14?.50:.83),lo=0,hi=4;for(int i=0;i<30;++i){double mid=(lo+hi)*.5;if(race.at(0,mid).cycles<target)lo=mid;else hi=mid;}simulation=(lo+hi)*.5;Vec3 p=boatPosition(0,simulation);aim(p+Vec3{3.8,4.5,8.5},p+Vec3{.2,.8,0});action=frame==13?"STROKE | CATCH: blades enter beside the gunwale; hands follow the paddle.":frame==14?"STROKE | DRIVE: buried blades pull back, crew stays synchronized.":"STROKE | RECOVERY: blades clear the water and return through the air.";}
 if(frame>=16&&frame<=18){trajectory=true;simulation=frame==16?5:frame==17?15:26;preset(3);action="PACE | Independent acceleration, middle-race surge and final sprint.";logFile<<"Race sample "<<simulation<<" red_distance="<<race.at(0,simulation).distance*raceScale()<<" jade_distance="<<race.at(1,simulation).distance*raceScale()<<" red_speed="<<race.at(0,simulation).speed*raceScale()<<" jade_speed="<<race.at(1,simulation).speed*raceScale()<<"\n";}
 if(frame>=19&&frame<=21){reset();selected=0;models[2].translation.y=-100;trajectory=true;double target=frame==19?.1:frame==20?.64:1.1,lo=0,hi=4;for(int i=0;i<30;++i){double mid=(lo+hi)*.5;if(race.at(0,mid).cycles<target)lo=mid;else hi=mid;}simulation=(lo+hi)*.5;Vec3 p=boatPosition(0,simulation);aim(p+Vec3{6.6,3.1,4.2},p+Vec3{3.65,1.5,0});action=frame==19?"DRUM | Right-hand strike: contact at the paddle catch, left hand raised.":frame==20?"DRUM | Rebound and preparation: hands remain attached to the sticks.":"DRUM | Left-hand strike: alternate hands on successive paddle strokes.";logFile<<"Drum sample "<<target<<" right_tip_y="<<drumTip(target,1).y<<" left_tip_y="<<drumTip(target,-1).y<<"\n";}
 if(frame==22||frame==23){reset();selected=0;models[2].translation.y=-100;trajectory=true;simulation=frame==22?2:2.4;Vec3 p=boatPosition(0,simulation);aim(p+Vec3{-6.3,3.5,3.4},p+Vec3{-4.05,2.68,-.18});action="FLAG | Pole edge pinned; free edge ripples with wind and boat speed.";}
 if(frame==24){reset();trajectory=true;simulation=3;key(VK_SPACE);tick(.1);key(VK_SPACE);double paused=simulation,phase=crewPhase(0);tick(.4);if(simulation!=paused||crewPhase(0)!=phase)throw std::runtime_error("Paused boat/crew/flag time changed");key(VK_SPACE);SendMessage(windowHandle,WM_LBUTTONDOWN,0,MAKELPARAM(400,400));SendMessage(windowHandle,WM_LBUTTONUP,0,0);tick(.2);if(playing||simulation!=paused)throw std::runtime_error("Mouse inspection failed to freeze animation");key(VK_TAB);Vec3 red=models[0].translation,jade=models[1].translation;keys[VK_RIGHT]=true;tick(.2);keys[VK_RIGHT]=false;if(selected!=1||length(models[0].translation-red)>1e-8||models[1].translation.x-jade.x<.79)throw std::runtime_error("Selected jade boat control affected the wrong model");logFile<<"Pause and selection PASS\n";}
 if(frame==34||frame==35){reset();trajectory=true;simulation=frame==34?1.05:3.15;clockTime=simulation;frustumCullingEnabled=shadowsEnabled=lighting=mapping=normalMaps=environment=true;models[1].translation.y=-100;models[2].translation.y=-100;Vec3 p=boatPosition(0,simulation);cameraFov=55;aim(p+Vec3{-2.9,3.0,3.1},p+Vec3{-4.6,1.5,.5});action="STEERING | Both hands follow the long oar; feet planted; shaft stays aft and outboard.";}
