 if(frame>=24&&frame<=29){reset();selected=0;models[2].translation.y=-100;trajectory=true;const double times[]={0,4,10,16,21,26};simulation=times[frame-24];preset(3);checkCinematicFrame();action=flight.stage(simulation);}
